content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  padding: 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: #1b1b1f;
  background: #f6f6f8;
}

.container {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: #ffffff;
  border: 1px solid #d6d6dd;
  border-radius: 8px;
  padding: 16px;
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 16px;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.task-form,
.filter-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
}

label {
  flex: 0 0 auto;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}

#new-task {
  flex: 1 1 12rem;
  min-width: 0;
  max-width: 100%;
  padding: 8px;
  font: inherit;
  color: inherit;
  border: 1px solid #6b6b76;
  border-radius: 4px;
  background: #ffffff;
}

#filter {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 100%;
  padding: 8px;
  font: inherit;
  color: inherit;
  border: 1px solid #6b6b76;
  border-radius: 4px;
  background: #ffffff;
}

button {
  flex: 0 1 auto;
  max-width: 100%;
  padding: 8px 14px;
  font: inherit;
  color: #ffffff;
  background: #2b4d8f;
  border: 1px solid #24407a;
  border-radius: 4px;
  cursor: pointer;
  overflow-wrap: anywhere;
  word-break: break-word;
}

button:hover {
  background: #24407a;
}

:focus-visible {
  outline: 3px solid #b03a1a;
  outline-offset: 2px;
}

#task-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

#task-list > li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-top: 1px solid #e2e2e8;
}

#task-list > li:first-child {
  border-top: 0;
}

.task-text {
  flex: 1 1 10rem;
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.task-complete {
  flex: 0 0 auto;
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
}

.task-delete {
  flex: 0 0 auto;
}
